def compute(vars):
    previous = vars["v1"]
    current = vars["v2"]

    if previous == 0:
        return None

    difference = current - previous
    growth_rate = difference / previous * 100

    return {
        "value": growth_rate,
        "trace": {
            "previous_value": previous,
            "current_value": current,
            "difference": difference,
            "formula": "(current - previous) / previous * 100",
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "%"
            }
        }
    }
